exec(open('tools/common.py').read())
# Intermediate unit 7 – Get. Bám sách: trang 18–19 (đã xem ảnh trang) + đáp án + Mini dictionary. Không chép nguyên văn.
# get on (hợp nhau – u2; làm tiếp – u5), get away (u2), get away with (cách chưa tốt nhất – u1) đã có thẻ → chỉ nhắc trong lý thuyết.
theory = (
 H("A", "Learning phrasal verbs in pairs associated with a context", "Học phrasal verb theo cặp gắn với một ngữ cảnh")
 + T([
   ("get together (often + with)", "meet in order to do something or spend time together", "gặp nhau để cùng làm gì hoặc cùng chơi"),
   ("get on (often + with)", "like each other and be friendly (card in Unit 2)", "hợp nhau, thân thiện (đã có thẻ ở bài 2)"),
   ("get on (often + with)", "continue doing something, especially work (card in Unit 5)", "làm tiếp việc gì, nhất là công việc (đã có thẻ ở bài 5)"),
   ("get behind (often + with)", "fall behind schedule with your work or with payments", "bị chậm, tồn đọng việc hoặc khoản phải trả so với hạn"),
   ("get sth over with", "do and finish something difficult or unpleasant that must be done", "làm cho xong việc khó/khó chịu buộc phải làm"),
   ("get away", "leave a place or person when it is difficult to do so (card in Unit 2)", "rời đi khi khó mà đi được (đã có thẻ ở bài 2)"),
   ("can’t / couldn’t get over sth", "be very surprised or shocked that something is true or has happened", "không thể tin nổi, rất ngạc nhiên hoặc sốc"),
   ("get away with sth / doing sth", "not be criticised or punished for something wrong you have done", "làm sai mà không bị phê bình hay trừng phạt"),
 ])
 + P("The book pairs the verbs in short examples: it’s nice to <b>get together</b> with people you <b>get on</b> with; a person who should <b>get on</b> with their work <b>got behind</b> by spending too long online; let’s <b>get</b> the meeting <b>over with</b> or we’ll never <b>get away</b> before the rush hour; I <b>can’t get over</b> how a colleague <b>gets away with</b> doing so little work.",
     "Sách ghép các động từ thành cặp trong ví dụ ngắn: thật vui khi <b>get together</b> với người mình <b>get on</b> với; người cần <b>get on</b> với việc lại <b>got behind</b> vì lên mạng quá lâu; hãy <b>get</b> cuộc họp <b>over with</b> kẻo không <b>get away</b> trước giờ cao điểm; tôi <b>can’t get over</b> chuyện một đồng nghiệp <b>gets away with</b> việc làm quá ít.")
 + H("B", "More phrasal verbs with get", "Thêm phrasal verb với get")
 + P("Short dialogues show five more: someone without a job <b>gets by</b> with help from their parents (has just enough money); a rule about next year’s budget is a problem, but they will <b>get around/round</b> it (find a way of dealing with it); someone hasn’t <b>got around/round to</b> confirming travel bookings (hasn’t yet done something they intended to); a person doesn’t know what the other is <b>getting at</b> (means, when it is said indirectly); a speaker hopes to <b>get away with</b> not using handouts (do something successfully although it is not the best way – card in Unit 1).",
     "Các đoạn hội thoại ngắn giới thiệu thêm năm cụm: người thất nghiệp <b>gets by</b> nhờ bố mẹ giúp (vừa đủ tiền sống); quy định về ngân sách năm sau là vấn đề, nhưng họ sẽ <b>get around/round</b> nó (tìm cách xử lý, lách qua); ai đó chưa <b>got around/round to</b> việc xác nhận đặt chỗ du lịch (chưa làm việc vốn định làm); một người không hiểu người kia đang <b>getting at</b> gì (ám chỉ gì khi nói vòng vo); người thuyết trình mong <b>get away with</b> việc không phát tài liệu (làm vẫn được dù không phải cách tốt nhất – đã có thẻ ở bài 1).")
 + NOTE("<b>Over to you</b>: learning verbs in pairs linked to one context helps you remember them – make your own pairs from this page and put them in sentences, as in section A.",
        "<b>Over to you</b>: học động từ theo cặp gắn với một ngữ cảnh giúp nhớ lâu – hãy tự ghép cặp từ trang này và đặt câu, như ở mục A.")
)
